 public static void Install(TerrierMatch m){var old=GameObject.Find("The colossal ice cream catch bowl");if(old!=null)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("The colossal ice cream catch bowl").transform;root.SetPositionAndRotation(m.course.World(new Vector3(0,-29,85)),m.course.Heading);var d=m.gameObject.GetComponent<TerrierDessert>()??m.gameObject.AddComponent<TerrierDessert>();m.dessert=d;d.match=m;var system=new GameObject("Dessert physical surface").transform;system.SetParent(root,false);// Basin coordinates are separate from the match authority.
 d.basin=root;
 var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckTerrierRacing/Art/IceCream/SM_PROP_bowl_metal.fbx");if(model==null)throw new Exception("Imported actual bowl model missing");var art=UnityEngine.Object.Instantiate(model,root,false);art.name="Actual enormous metal dessert bowl";Bounds bounds=default;bool first=true;foreach(var f in art.GetComponentsInChildren<MeshFilter>(true)){var b=f.sharedMesh.bounds;for(int i=0;i<8;i++){var p=art.transform.InverseTransformPoint(f.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}}
