 var flavors=new[]{SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Vanilla bean",new Color(1,.86f,.61f),.28f),SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Strawberry cream",new Color(.94f,.36f,.48f),.32f),SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Chocolate fudge",new Color(.25f,.085f,.043f),.38f)};
 var mesh=Surface(98,155,false);mesh=SaveMesh(mesh,"Sculpted ice cream surface");system.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=system.gameObject.AddComponent<MeshRenderer>();renderer.sharedMaterials=flavors;d.cream=system;var collision=Surface(98,155,true);collision=SaveMesh(collision,"Dessert cushion collision");var contact=SportsEventAuthoring.Contact(TerrierAuthoring.Folder,"Soft ice cream",.65f,.015f);var collider=system.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=collision;collider.sharedMaterial=contact;
