 var sprinkles=new GameObject("Hundreds of candy sprinkles");sprinkles.transform.SetParent(root,false);var topping=new Mesh();var verts=new List<Vector3>();var triangles=new List<int>();var colors=new List<Color>();var random=new System.Random(7481);for(int k=0;k<340;k++){float x=((float)random.NextDouble()*2-1)*94,z=((float)random.NextDouble()*2-1)*149;if(x*x/(94*94)+z*z/(149*149)>1)continue;float y=TerrierDessert.Profile(x,z)+.07f;var v=new Vector3(x,y,z);var a=new Vector3(Mathf.Cos(k)*.38f,.035f,Mathf.Sin(k)*.38f);var b=Vector3.Cross(a,Vector3.up).normalized*.10f;int n=verts.Count;verts.AddRange(new[]{v-a-b,v+a-b,v+a+b,v-a+b});triangles.AddRange(new[]{n,n+2,n+1,n,n+3,n+2});var color=Color.HSVToRGB((k*.618f)%1,.72f,1);for(int q=0;q<4;q++)colors.Add(color);}topping.SetVertices(verts);topping.SetTriangles(triangles,0);topping.SetColors(colors);topping.RecalculateNormals();topping=SaveMesh(topping,"Dessert sprinkle mesh");sprinkles.AddComponent<MeshFilter>().sharedMesh=topping;sprinkles.AddComponent<MeshRenderer>().sharedMaterial=SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Sugar sprinkles",new Color(1,.57f,.75f),.45f);
