 static Mesh Surface(float rx,float rz,bool physics){const int rings=28,segments=128;var vertices=new List<Vector3>();var uv=new List<Vector2>();var tris=new[]{new List<int>(),new List<int>(),new List<int>()};for(int r=0;r<=rings;r++){float f=r/(float)rings;for(int j=0;j<=segments;j++){float angle=j*Mathf.PI*2/segments;float x=Mathf.Cos(angle)*rx*f,z=Mathf.Sin(angle)*rz*f;float h=TerrierDessert.Profile(x,z)-(physics?1.35f:0);vertices.Add(new Vector3(x,h,z));uv.Add(new Vector2(x*.04f,z*.04f));}}for(int r=0;r<rings;r++)for(int j=0;j<segments;j++){int a=r*(segments+1)+j,b=a+segments+1;float cx=(vertices[a].x+vertices[b].x)*.5f;int flavor=physics?0:cx< -28?1:cx>28?2:0;tris[flavor].AddRange(new[]{a,b+1,b,a,a+1,b+1});}var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.subMeshCount=3;for(int i=0;i<3;i++)mesh.SetTriangles(tris[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
 static Mesh SaveMesh(Mesh mesh,string name){string path="Assets/TruckTerrierRacing/Art/IceCream/"+name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing==null)AssetDatabase.CreateAsset(mesh,path);else{existing.Clear();existing.vertices=mesh.vertices;existing.normals=mesh.normals;existing.uv=mesh.uv;existing.colors=mesh.colors;existing.subMeshCount=mesh.subMeshCount;for(int i=0;i<mesh.subMeshCount;i++)existing.SetTriangles(mesh.GetTriangles(i),i);existing.RecalculateBounds();existing.UploadMeshData(false);EditorUtility.SetDirty(existing);UnityEngine.Object.DestroyImmediate(mesh);return existing;}return mesh;}
